```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mocks - even Harvard residents must occasionally work with simulacra
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Fine Cognac', price: 299.99 },
  { id: '2', name: 'Opera Tickets', price: 450.00 },
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockCartItems, total: 749.99, clearCart: mockClearCart }),
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // Happy Path - The proper way things should proceed
  describe('Complete Checkout Flow', () => {
    it('navigates through all steps and completes order', async () => {
      render(<Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Beacon Hill');
      await user.type(screen.getByLabelText(/city/i), 'Boston');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '02108');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Charles E Winchester III');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/fine cognac/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText(/ORD-12345/)).toBeInTheDocument();
      });
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // Validation - Standards must be maintained
  describe('Form Validation', () => {
    it('displays shipping errors for empty required fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // Error Recovery - Even surgeons encounter complications
  describe('Payment Failure Handling', () => {
    it('displays error and allows retry after payment failure', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);
      // ... navigate to review step

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // Accessibility - Proper standards for civilized society
  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
